use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters, per the node contract.
const MAX_QUESTION_CHARS: usize = 512;

/// Used only when the knowledge base returns nothing, so `knowledge` is never empty.
const NO_KNOWLEDGE: &str = "No relevant knowledge base entries were found for this query.";

fn bound_question(question: String) -> String {
    if question.chars().count() > MAX_QUESTION_CHARS {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    } else {
        question
    }
}

fn add_entries(knowledge: &mut Vec<String>, entries: Vec<String>) {
    for entry in entries {
        if entry.trim().is_empty() {
            continue;
        }
        if knowledge.iter().any(|k| *k == entry) {
            continue;
        }
        knowledge.push(entry);
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;
        let question = bound_question(inner.question);

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the bounded question itself.
        add_entries(&mut knowledge, kb_read::lookup(&question));

        // Fallback: try the extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                let entity = entity.trim();
                if entity.is_empty() {
                    continue;
                }
                add_entries(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // The contract requires knowledge to be present.
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
